package main

import (
	"fmt"
	"io"
	"net/http"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

// FileConverterService handles document conversion requests
type FileConverterService struct {
	workDir    string
	convertBin string
}

func NewFileConverterService() *FileConverterService {
	workDir := os.Getenv("WORK_DIR")
	if workDir == "" {
		workDir = "/tmp/conversions"
	}
	os.MkdirAll(workDir, 0755)
	return &FileConverterService{
		workDir:    workDir,
		convertBin: "/usr/bin/libreoffice",
	}
}

func (s *FileConverterService) handleConvert(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	outputFormat := r.URL.Query().Get("format")
	if outputFormat == "" {
		outputFormat = "pdf"
	}

	// Basic format validation
	allowedFormats := []string{"pdf", "docx", "xlsx", "pptx", "odt", "html", "txt"}
	formatValid := false
	for _, f := range allowedFormats {
		if f == outputFormat {
			formatValid = true
			break
		}
	}
	if !formatValid {
		http.Error(w, "Invalid output format", 400)
		return
	}

	file, header, err := r.FormFile("document")
	if err != nil {
		http.Error(w, "No file provided", 400)
		return
	}
	defer file.Close()

	// Sanitize filename - remove path traversal attempts
	filename := filepath.Base(header.Filename)
	filename = strings.ReplaceAll(filename, "..", "")

	inputPath := filepath.Join(s.workDir, filename)
	outFile, err := os.Create(inputPath)
	if err != nil {
		http.Error(w, "Failed to save file", 500)
		return
	}
	io.Copy(outFile, file)
	outFile.Close()

	// Convert using LibreOffice in headless mode
	// The filename is used directly in the command construction
	cmdArgs := fmt.Sprintf("--headless --convert-to %s --outdir %s %s",
		outputFormat, s.workDir, inputPath)

	cmd := exec.Command("/bin/sh", "-c", s.convertBin+" "+cmdArgs)
	cmd.Dir = s.workDir
	output, err := cmd.CombinedOutput()
	if err != nil {
		http.Error(w, fmt.Sprintf("Conversion failed: %s\n%s", err, string(output)), 500)
		os.Remove(inputPath)
		return
	}

	// Determine output filename
	ext := "." + outputFormat
	baseName := strings.TrimSuffix(filename, filepath.Ext(filename))
	outputPath := filepath.Join(s.workDir, baseName+ext)

	w.Header().Set("Content-Disposition", fmt.Sprintf("attachment; filename=%q", baseName+ext))
	http.ServeFile(w, r, outputPath)

	// Cleanup
	os.Remove(inputPath)
	os.Remove(outputPath)
}

func (s *FileConverterService) handleHealth(w http.ResponseWriter, r *http.Request) {
	w.Write([]byte(`{"status":"healthy","version":"2.4.1"}`))
}

func main() {
	svc := NewFileConverterService()
	http.HandleFunc("/convert", svc.handleConvert)
	http.HandleFunc("/health", svc.handleHealth)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	fmt.Printf("File converter listening on :%s\n", port)
	http.ListenAndServe(":"+port, nil)
}
